mapper.select:
SELECT COUNT(*) > 0
FROM trips
WHERE id = #{tripId}
  AND user_id = #{userId}
  AND is_deleted = 0

SELECT COUNT(*) > 0
FROM trip_countries trip_country
         INNER JOIN trips trip
                    ON trip.id = trip_country.trip_id
WHERE trip_country.trip_id = #{tripId}
  AND trip_country.country_id = #{countryId}
  AND trip_country.is_deleted = 0
  AND trip.user_id = #{userId}
  AND trip.is_deleted = 0

SELECT COUNT(*) > 0
FROM spending_categories
WHERE id = #{categoryId}

SELECT id
FROM currencies
WHERE currency_code = #{currencyCode}

mapper.update:
UPDATE receipt_items item
    INNER JOIN receipts receipt
    ON receipt.id = item.receipt_id
SET item.is_deleted = 1,
    item.deleted_at = NOW()
WHERE item.receipt_id = #{receiptId}
  AND receipt.user_id = #{userId}
  AND receipt.trip_id = #{tripId}
  AND receipt.is_deleted = 0
  AND item.is_deleted = 0

UPDATE receipt_participants participant
    INNER JOIN receipts receipt
    ON receipt.id = participant.receipt_id
SET participant.is_deleted = 1,
    participant.deleted_at = NOW()
WHERE participant.receipt_id = #{receiptId}
  AND receipt.user_id = #{userId}
  AND receipt.trip_id = #{tripId}
  AND receipt.is_deleted = 0
  AND participant.is_deleted = 0

UPDATE receipts
SET is_deleted = 1,
    deleted_at = NOW()
WHERE id = #{receiptId}
  AND user_id = #{userId}
  AND trip_id = #{tripId}
  AND is_deleted = 0
